"use strict";(self.webpackChunkbuhaoqi_github_io=self.webpackChunkbuhaoqi_github_io||[]).push([["57057"],{57197(n,e,r){r.r(e),r.d(e,{metadata:()=>t,default:()=>u,frontMatter:()=>o,contentTitle:()=>a,toc:()=>l,assets:()=>d});var t=JSON.parse('{"id":"csharp-tutorials/0403","title":"4\u67083\u65E5 \u5B57\u7B26\u4E32\u7EC3\u4E60\u9898","description":"\u731C\u5B57\u6BCD\u6E38\u620F","source":"@site/docs/csharp-tutorials/0403.md","sourceDirName":"csharp-tutorials","slug":"/csharp-tutorials/0403","permalink":"/docs/csharp-tutorials/0403","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/csharp-tutorials/0403.md","tags":[],"version":"current","sidebarPosition":10,"frontMatter":{"title":"4\u67083\u65E5 \u5B57\u7B26\u4E32\u7EC3\u4E60\u9898","sidebar_label":"4\u67083\u65E5 \u5B57\u7B26\u4E32\u7EC3\u4E60\u9898","sidebar_position":10}}'),i=r(74848),s=r(28453);let o={title:"4\u67083\u65E5 \u5B57\u7B26\u4E32\u7EC3\u4E60\u9898",sidebar_label:"4\u67083\u65E5 \u5B57\u7B26\u4E32\u7EC3\u4E60\u9898",sidebar_position:10},a,d={},l=[{value:"\u731C\u5B57\u6BCD\u6E38\u620F",id:"\u731C\u5B57\u6BCD\u6E38\u620F",level:2}];function c(n){let e={code:"code",h2:"h2",pre:"pre",...(0,s.R)(),...n.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(e.h2,{id:"\u731C\u5B57\u6BCD\u6E38\u620F",children:"\u731C\u5B57\u6BCD\u6E38\u620F"}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-csharp",children:' // \u6E38\u620F\u6807\u9898\n Console.WriteLine("==================================");\n Console.WriteLine("    \u{1F3AE} \u6587\u5B57\u731C\u8C1C\u5927\u6311\u6218 \u{1F3AE}");\n Console.WriteLine("==================================");\n Console.WriteLine("\u63D0\u793A\uFF1A\u8F93\u5165\u4E00\u4E2A\u5B57\u6BCD\u6765\u731C\uFF0C\u731C\u5BF9\u4F1A\u663E\u793A\uFF0C\u9519\u4E86\u6263\u751F\u547D\u503C\uFF5E\\n");\n\n // \u968F\u673A\u5355\u8BCD\u5E93\n string[] words = { "apple", "banana", "computer", "student", "family", "hello", "unity" };\n Random random = new Random();\n string answer = words[random.Next(words.Length)]; // \u968F\u673A\u9009\u4E00\u4E2A\u7B54\u6848\n\n // \u6F14\u793A\u5B57\u7B26\u4E32\u6280\u80FD\uFF1ALength\u3001Replace\u3001ToUpper\n Console.WriteLine($"\u3010\u6280\u80FD\u6F14\u793A\u3011\u5355\u8BCD\u957F\u5EA6\uFF1A{answer.Length} \u4E2A\u5B57\u6BCD");\n string demoReplace = answer.Replace("a", "@");\n Console.WriteLine($"\u3010\u6280\u80FD\u6F14\u793A\u3011\u5C06\u5355\u8BCD\u4E2D\u7684 \'a\' \u66FF\u6362\u4E3A \'@\'\uFF1A{demoReplace}");\n string demoUpper = answer.ToUpper();\n Console.WriteLine($"\u3010\u6280\u80FD\u6F14\u793A\u3011\u5355\u8BCD\u5927\u5199\u5F62\u5F0F\uFF1A{demoUpper}\\n");\n\n // \u751F\u6210\u9690\u85CF\u6587\u5B57\uFF1A\u9996\u5B57\u6BCD\u663E\u793A\uFF0C\u5176\u4F59\u53D8 *\n char[] hidden = answer.ToCharArray();\n for (int i = 1; i < hidden.Length; i++)\n {\n     hidden[i] = \'*\';\n }\n string hiddenWord = new string(hidden);\n\n int life = 5;                     // \u751F\u547D\u503C\n List<char> guessedLetters = new List<char>(); // \u8BB0\u5F55\u5DF2\u731C\u8FC7\u7684\u5B57\u6BCD\uFF08\u5927\u5199\u5B58\u50A8\uFF0C\u4FBF\u4E8E\u6BD4\u8F83\uFF09\n\n // \u6E38\u620F\u4E3B\u5FAA\u73AF\n while (life > 0 && hiddenWord.Contains("*"))\n {\n     Console.WriteLine($"\\n\u5F53\u524D\u5355\u8BCD\uFF1A{string.Join(" ", hiddenWord.ToCharArray())}"); // \u7A7A\u683C\u5206\u9694\u66F4\u6E05\u6670\n     Console.WriteLine($"\u5269\u4F59\u751F\u547D\u503C\uFF1A{life}");\n     Console.Write("\u8BF7\u8F93\u5165\u4E00\u4E2A\u5B57\u6BCD\uFF1A");\n\n     string input = Console.ReadLine();\n     // \u8F93\u5165\u9A8C\u8BC1\uFF1A\u4E0D\u80FD\u4E3A\u7A7A\uFF0C\u4E14\u5FC5\u987B\u662F\u5355\u4E2A\u5B57\u6BCD\n     if (string.IsNullOrEmpty(input) || input.Length != 1 || !char.IsLetter(input[0]))\n     {\n         Console.WriteLine("\u274C \u65E0\u6548\u8F93\u5165\uFF01\u8BF7\u8F93\u5165\u4E00\u4E2A\u5B57\u6BCD\uFF08a-z \u6216 A-Z\uFF09\u3002");\n         continue;\n     }\n\n     char guess = char.ToUpper(input[0]);   // \u7EDF\u4E00\u8F6C\u5927\u5199\u5B58\u50A8\uFF0C\u65B9\u4FBF\u53BB\u91CD\u6BD4\u8F83\n     char guessLower = char.ToLower(guess); // \u5C0F\u5199\u7528\u4E8E\u4E0E\u5355\u8BCD\u6BD4\u8F83\n\n     // \u68C0\u67E5\u662F\u5426\u5DF2\u7ECF\u731C\u8FC7\u8FD9\u4E2A\u5B57\u6BCD\n     if (guessedLetters.Contains(guess))\n     {\n         Console.WriteLine($"\u26A0\uFE0F \u5B57\u6BCD \'{guess}\' \u5DF2\u7ECF\u731C\u8FC7\u4E86\uFF0C\u8BF7\u6362\u4E00\u4E2A\uFF01");\n         continue;\n     }\n     guessedLetters.Add(guess);\n\n     // \u4F7F\u7528 Contains \u5224\u65AD\u5B57\u6BCD\u662F\u5426\u5728\u5355\u8BCD\u4E2D\uFF08\u6280\u80FD\u6F14\u793A\uFF09\n     bool isCorrect = answer.Contains(guessLower);\n     // \u4E5F\u53EF\u7528 IndexOf \u6F14\u793A\uFF08\u6280\u80FD\u6F14\u793A\uFF09\n     int index = answer.IndexOf(guessLower);\n     if (index >= 0)\n     {\n         // \u4EC5\u6F14\u793A IndexOf \u7684\u7528\u6CD5\uFF0C\u4E0D\u989D\u5916\u5904\u7406\n         // Console.WriteLine($"\u8C03\u8BD5\uFF1A\u5B57\u6BCD\u9996\u6B21\u51FA\u73B0\u5728\u4F4D\u7F6E {index}");\n     }\n\n     if (isCorrect)\n     {\n         Console.WriteLine("\u2705 \u606D\u559C\uFF01\u731C\u5BF9\u4E86\uFF01");\n\n         // \u628A\u6240\u6709\u731C\u5BF9\u7684\u5B57\u6BCD\u663E\u793A\u51FA\u6765\uFF08\u4F7F\u7528 ToCharArray \u6280\u80FD\uFF09\n         char[] temp = hiddenWord.ToCharArray();\n         for (int i = 0; i < answer.Length; i++)\n         {\n             if (answer[i] == guessLower)\n             {\n                 temp[i] = guessLower; // \u663E\u793A\u5C0F\u5199\u5B57\u6BCD\n             }\n         }\n         hiddenWord = new string(temp);\n     }\n     else\n     {\n         life--;\n         Console.WriteLine($"\u274C \u731C\u9519\u5566\uFF01\u751F\u547D\u503C-1\uFF0C\u5269\u4F59\uFF1A{life}");\n     }\n }\n\n // \u6E38\u620F\u7ED3\u675F\u5224\u65AD\n if (life == 0)\n {\n     Console.WriteLine("\\n\u{1F480} \u6E38\u620F\u7ED3\u675F\uFF01\u6B63\u786E\u7B54\u6848\u662F\uFF1A" + answer);\n }\n else\n {\n     Console.WriteLine("\\n\u{1F389} \u606D\u559C\u4F60\u8D62\u4E86\uFF01\u6B63\u786E\u7B54\u6848\uFF1A" + answer);\n }\n\n Console.ReadLine(); // \u9632\u6B62\u63A7\u5236\u53F0\u7ACB\u5373\u5173\u95ED\n'})})]})}function u(n={}){let{wrapper:e}={...(0,s.R)(),...n.components};return e?(0,i.jsx)(e,{...n,children:(0,i.jsx)(c,{...n})}):c(n)}},28453(n,e,r){r.d(e,{R:()=>o,x:()=>a});var t=r(96540);let i={},s=t.createContext(i);function o(n){let e=t.useContext(s);return t.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function a(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(i):n.components||i:o(n.components),t.createElement(s.Provider,{value:e},n.children)}}}]);